/**
 * @file app/api/research/discover/route.ts
 * @description API Endpoint for Module 02: Information Discovery Engine.
 *
 * Subsystem:
 * Autonomous Knowledge & Research Intelligence - Discovery Endpoint.
 *
 * Key Responsibilities:
 * - Accepts a `ResearchPlan` payload generated by Module 01.
 * - Concurrently invokes registered discovery provider adapters (Web, GitHub, Academic, Internal Docs, Memory).
 * - Enforces the 6-tier credibility priority policy.
 * - Persists discovered source entities into `researchRepository`.
 * - Returns prioritized and deduplicated sources to the caller.
 *
 * Architectural Role & Interactions:
 * - Upstream: Consumes output from `app/api/research/plan/route.ts`.
 * - Downstream: Feeds discovered sources to `app/api/research/extract/route.ts`.
 *
 * Safety / Security Guarantees:
 * - Read-only discovery: Zero state changes on external networks.
 * - SSRF filter: Prevents loopback, private IP, and metadata target probes.
 */

import { NextRequest, NextResponse } from "next/server";
import { informationDiscoveryEngine, normalizeUrl } from "@/lib/research/discoveryEngine";
import { researchRepository } from "@/lib/research/repository";
import { validateDesktopSession, createAuthErrorResponse } from "@/lib/sessionGate";
import type { ResearchPlan, SourceRecord } from "@/lib/research/types";

export async function POST(req: NextRequest): Promise<NextResponse> {
  const auth = validateDesktopSession(req);
  if (!auth.valid) {
    return createAuthErrorResponse(auth);
  }

  try {
    let body: { plan: ResearchPlan };
    try {
      body = await req.json();
    } catch {
      return NextResponse.json({ error: "Invalid JSON request payload" }, { status: 400 });
    }

    if (!body || !body.plan || !body.plan.research_id || !Array.isArray(body.plan.search_strategy)) {
      return NextResponse.json({ error: "A valid, structured ResearchPlan object is required" }, { status: 400 });
    }

    const { plan } = body;

    // 1. Execute Multi-Source Discovery
    await researchRepository.updateProjectStatus(plan.research_id, "discovering");
    const discoveredItems = await informationDiscoveryEngine.discoverAll(plan);

    // 2. Persist Discovered Sources in Shared Repository
    const sourceRecords: SourceRecord[] = discoveredItems.map((item) => {
      const { hash } = normalizeUrl(item.canonical_url || item.original_url);
      return {
        id: item.discovery_id,
        project_id: plan.research_id,
        query_id: item.query_id,
        title: item.title,
        original_url: item.original_url,
        canonical_url: item.canonical_url,
        canonical_url_hash: hash,
        source_type: item.source_type,
        publisher: item.publisher,
        author: item.author,
        snippet: item.snippet,
        provider: item.provider,
        provider_metadata: item.provider_metadata,
        publication_date: item.publication_date,
        discovered_at: item.discovered_at,
        retrieval_status: item.retrieval_status,
        content_availability: item.content_availability,
        created_at: item.discovered_at,
        updated_at: item.discovered_at,
      };
    });

    const savedSources = await researchRepository.saveSources(sourceRecords);

    return NextResponse.json({
      success: true,
      research_id: plan.research_id,
      sourcesCount: savedSources.length,
      sources: savedSources,
    });
  } catch (err: unknown) {
    console.error("[RESEARCH DISCOVER API ERROR]", err);
    const message = err instanceof Error ? err.message : "Internal research discovery failure";
    return NextResponse.json({ success: false, error: message }, { status: 500 });
  }
}
